export const assets = Object.freeze({
  "./overview.html": "<!doctype html>\n<html lang=\"id\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>CHARISNA — Ringkasan Pemilik</title><link rel=\"stylesheet\" href=\"/styles.css\"><link rel=\"stylesheet\" href=\"/money.css\"><script type=\"module\" src=\"/app.mjs\"></script></head>\n<body>\n<a class=\"skip\" href=\"#main\">Lewati ke ringkasan</a>\n<header class=\"topbar\"><a class=\"brand\" href=\"/\" aria-label=\"CHARISNA SuperApp, beranda\"><span class=\"brand-mark\" aria-hidden=\"true\">C</span><span>CHARISNA <small>SUPERAPP</small></span></a><div class=\"identity\"><span class=\"demo-label\">Sumber nyata</span><span class=\"role\">Pemilik</span><a class=\"button secondary\" href=\"/security\">Keamanan</a><form id=\"logout-form\" action=\"/auth/logout\" method=\"post\"><button id=\"logout-button\" class=\"button secondary\" type=\"submit\">Keluar</button></form></div></header>\n<main id=\"main\" class=\"live-main\"><div class=\"page-heading\"><div><p class=\"eyebrow\">BERANDA PEMILIK</p><h1>Ringkasan penghasilan<span class=\"title-dot\">.</span></h1><p class=\"subtitle\">Data MySalary dibaca langsung dari akun yang Anda hubungkan.</p></div><p class=\"period\"><span class=\"period-dot\" aria-hidden=\"true\"></span><span id=\"period\">Menunggu data</span><small>Waktu Indonesia Barat</small></p></div>\n<div class=\"demo-note\"><span class=\"note-icon\" aria-hidden=\"true\">i</span><p>Gaji mengajar adalah penghasilan pribadi dalam USD. Nilainya tidak digabung dengan omzet usaha atau saldo.</p></div>\n<p id=\"load-status\" role=\"status\" class=\"field-hint\" style=\"margin-bottom:14px\">Memuat ringkasan MySalary…</p>\n<div id=\"skeleton-panel\" class=\"skeleton-panel businesses\" aria-hidden=\"true\">\n  <div class=\"section-heading\"><span class=\"skeleton skeleton-title\" style=\"width:230px\"></span><span class=\"skeleton skeleton-badge\"></span></div>\n  <div class=\"business-grid live-stats\">\n    <div class=\"business-card\"><span class=\"skeleton skeleton-text\" style=\"width:110px\"></span><span class=\"skeleton skeleton-value\"></span><span class=\"skeleton skeleton-text\" style=\"width:170px\"></span></div>\n    <div class=\"business-card\"><span class=\"skeleton skeleton-text\" style=\"width:110px\"></span><span class=\"skeleton skeleton-value\"></span><span class=\"skeleton skeleton-text\" style=\"width:140px\"></span></div>\n    <div class=\"business-card\"><span class=\"skeleton skeleton-text\" style=\"width:110px\"></span><span class=\"skeleton skeleton-value\"></span><span class=\"skeleton skeleton-text\" style=\"width:180px\"></span></div>\n    <div class=\"business-card\"><span class=\"skeleton skeleton-text\" style=\"width:110px\"></span><span class=\"skeleton skeleton-value\"></span><span class=\"skeleton skeleton-text\" style=\"width:130px\"></span></div>\n  </div>\n  <div style=\"margin-top:28px\">\n    <span class=\"skeleton skeleton-title\" style=\"width:140px;height:18px;margin-bottom:12px\"></span>\n    <span class=\"skeleton skeleton-row\"></span>\n    <span class=\"skeleton skeleton-row\"></span>\n    <span class=\"skeleton skeleton-row\"></span>\n  </div>\n</div>\n<section id=\"connect-panel\" class=\"login-card live-panel\" hidden aria-labelledby=\"connect-title\"><p class=\"eyebrow\">SAMBUNGKAN SUMBER</p><h2 id=\"connect-title\">Hubungkan MySalary sekali</h2><p class=\"login-description\">Masukkan akun MySalary. Sandi dikirim langsung ke Firebase. Token akses lanjutan disimpan terenkripsi di D1 agar sinkron tetap berjalan saat MySalary ditutup. Putuskan koneksi untuk menghapusnya.</p><form id=\"connect-form\"><label for=\"source-email\">Email MySalary</label><input id=\"source-email\" type=\"email\" autocomplete=\"username\" required><label for=\"source-password\">Sandi MySalary</label><input id=\"source-password\" type=\"password\" autocomplete=\"current-password\" required><button id=\"connect-button\" class=\"button primary\" type=\"submit\">Hubungkan akun</button></form><p id=\"connect-status\" role=\"status\" aria-live=\"polite\"></p></section>\n<section id=\"summary-panel\" class=\"businesses\" hidden aria-labelledby=\"summary-title\"><div class=\"section-heading\"><h2 id=\"summary-title\">MySalary · Teaching Pay Audit</h2><span id=\"quality\" class=\"badge\"></span></div><div class=\"business-grid live-stats\"><article class=\"business-card\"><p class=\"metric-label\">Gaji bulan terbaru</p><p id=\"latest-pay\" class=\"metric-value\">—</p><p class=\"metric-context\">USD · penghasilan mengajar, bukan omzet usaha</p></article><article class=\"business-card\"><p class=\"metric-label\">Jam bulan terbaru</p><p id=\"latest-hours\" class=\"metric-value\">—</p><p id=\"latest-days\" class=\"metric-context\"></p></article><article class=\"business-card\"><p class=\"metric-label\">Gaji tahun terbaru</p><p id=\"latest-year-pay\" class=\"metric-value\">—</p><p class=\"metric-context\">Total bulan tercatat tahun tersebut</p></article><article class=\"business-card\"><p class=\"metric-label\">Jam tahun terbaru</p><p id=\"latest-year-hours\" class=\"metric-value\">—</p><p id=\"latest-year\" class=\"metric-context\"></p></article></div><p id=\"sync-time\" class=\"scope-note\"></p><div class=\"table-header-bar\"><h3 class=\"live-table-title\" style=\"margin:0\">Rekap per bulan</h3><span id=\"month-count-pill\" class=\"table-hint-pill\">12 Bulan</span></div><div class=\"live-table-wrap live-table-scroll\"><table class=\"live-table\"><thead><tr><th>Bulan</th><th>Jam</th><th>Hari</th><th>Gaji (USD)</th></tr></thead><tbody id=\"month-rows\"></tbody></table></div><div class=\"table-header-bar\"><h3 class=\"live-table-title\" style=\"margin:0\">Rekap per tahun</h3></div><div class=\"live-table-wrap\"><table class=\"live-table\"><thead><tr><th>Tahun</th><th>Jam</th><th>Hari</th><th>Gaji (USD)</th></tr></thead><tbody id=\"year-rows\"></tbody></table></div><p class=\"scope-note\">Sumber: MySalary Firebase. Kelas dan catatan harian tidak disalin ke SuperApp. Sinkron terjadwal setiap 6 jam dan saat ringkasan dibuka setelah 1 jam.</p><button id=\"disconnect-button\" class=\"button secondary\" type=\"button\">Putuskan koneksi MySalary</button></section>\n<footer><span>CHARISNA SuperApp</span><span>Sumber nyata · hanya baca · khusus pemilik</span></footer></main>\n</body></html>\n",
  "./overview.mjs": "export const money = minor => minor == null ? '—' : new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(Number(minor) / 100);\nexport const monthLabel = key => new Intl.DateTimeFormat('id-ID', { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${key}-01T00:00:00Z`));\nconst post = body => ({ method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), cache: 'no-store' });\n\nexport function mount({ document = globalThis.document, window = globalThis.window, fetchImpl = globalThis.fetch } = {}) {\n  const $ = selector => document.querySelector(selector);\n  if (document.createElement && $('.page-heading')) {\n    const nav = document.createElement('nav'); nav.className = 'source-tabs'; nav.setAttribute('aria-label', 'Sumber data');\n    const teaching = document.createElement('a'); teaching.href = '/'; teaching.className = 'button primary'; teaching.setAttribute('aria-current', 'page'); teaching.textContent = 'Teaching Pay Audit';\n    const moneyTab = document.createElement('a'); moneyTab.href = '/money'; moneyTab.className = 'button secondary'; moneyTab.textContent = 'Money Management';\n    const posTab = document.createElement('a'); posTab.href = '/pos'; posTab.className = 'button secondary'; posTab.textContent = 'Bumi Makmur POS';\n    const kostTab = document.createElement('a'); kostTab.href = '/kost'; kostTab.className = 'button secondary'; kostTab.textContent = 'CHARISNA KOST';\n    nav.append(teaching, moneyTab, posTab, kostTab); $('.page-heading').before(nav);\n  }\n  let connecting = false;\n  function showConnection(message = '') {\n    $('#summary-panel').hidden = true;\n    $('#connect-panel').hidden = false;\n    $('#connect-panel').classList.add('fade-in');\n    $('#connect-status').textContent = message;\n    $('#load-status').hidden = true;\n    const skeleton = $('#skeleton-panel');\n    if (skeleton) skeleton.hidden = true;\n  }\n  function showSummary(data) {\n    $('#connect-panel').hidden = true;\n    $('#summary-panel').hidden = false;\n    $('#summary-panel').classList.add('fade-in');\n    $('#load-status').hidden = true;\n    const skeleton = $('#skeleton-panel');\n    if (skeleton) skeleton.hidden = true;\n\n    const rawMonths = Array.isArray(data.months) ? [...data.months].sort((a, b) => b.month.localeCompare(a.month)) : [];\n    const latestActive = rawMonths.find(m => m.hours > 0 || Number(m.pay_minor) > 0) || rawMonths[0];\n\n    $('#period').textContent = latestActive ? monthLabel(latestActive.month) : 'Belum ada bulan tercatat';\n    $('#latest-pay').textContent = latestActive ? money(latestActive.pay_minor) : '—';\n    $('#latest-hours').textContent = latestActive ? `${latestActive.hours} jam` : '—';\n    $('#latest-days').textContent = latestActive ? `${latestActive.teaching_days} hari mengajar` : 'Belum ada catatan bulan';\n\n    const years = Array.isArray(data.years) ? [...data.years].sort((a, b) => b.year.localeCompare(a.year)) : [];\n    const currentYear = years[0];\n    $('#latest-year-pay').textContent = currentYear ? money(currentYear.pay_minor) : '—';\n    $('#latest-year-hours').textContent = currentYear ? `${currentYear.hours} jam` : '—';\n    $('#latest-year').textContent = currentYear ? `Tahun ${currentYear.year}` : 'Belum ada catatan tahun';\n    $('#quality').textContent = data.state === 'stale' ? 'Data tertunda' : 'Dibaca dari sumber';\n    $('#quality').className = `badge ${data.state === 'stale' ? 'stale' : 'verified'}`;\n    $('#sync-time').textContent = data.synced_at ? `Dibaca ${new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Jakarta' }).format(new Date(data.synced_at))} WIB` : 'Waktu sinkron belum tersedia';\n\n    // Populate all months for each recorded year (e.g. 12 months per year)\n    const monthMap = new Map();\n    for (const m of rawMonths) monthMap.set(m.month, m);\n\n    const yearSet = new Set(years.map(y => String(y.year)));\n    if (!yearSet.size && rawMonths.length) {\n      for (const m of rawMonths) yearSet.add(m.month.slice(0, 4));\n    }\n    if (!yearSet.size) yearSet.add(String(new Date().getFullYear()));\n\n    const allMonths = [];\n    for (const y of [...yearSet].sort((a, b) => b.localeCompare(a))) {\n      for (let m = 12; m >= 1; m--) {\n        const key = `${y}-${String(m).padStart(2, '0')}`;\n        if (monthMap.has(key)) {\n          allMonths.push(monthMap.get(key));\n        } else {\n          allMonths.push({\n            month: key,\n            hours: 0,\n            teaching_days: 0,\n            pay_minor: '0',\n            currency: 'USD',\n            scale: 2\n          });\n        }\n      }\n    }\n\n    if ($('#month-count-pill')) {\n      $('#month-count-pill').textContent = `${allMonths.length} Bulan (Gulir)`;\n    }\n\n    const maxHours = Math.max(1, ...allMonths.map(m => m.hours || 0));\n    const rows = $('#month-rows');\n    rows.replaceChildren();\n    for (const item of allMonths) {\n      const row = document.createElement('tr');\n      const isZero = !item.hours && !Number(item.pay_minor);\n      const isLatest = latestActive && item.month === latestActive.month;\n      if (isLatest) row.className = 'row-current';\n      else if (isZero) row.className = 'row-zero';\n\n      // 1. Bulan cell\n      const monthCell = document.createElement('td');\n      const monthWrap = document.createElement('div');\n      monthWrap.className = 'cell-month-wrap';\n      const monthName = document.createElement('span');\n      monthName.className = 'month-name';\n      monthName.textContent = monthLabel(item.month);\n      monthWrap.append(monthName);\n      if (isLatest) {\n        const currentBadge = document.createElement('span');\n        currentBadge.className = 'badge-mini current';\n        currentBadge.textContent = 'Terbaru';\n        monthWrap.append(currentBadge);\n      }\n      monthCell.append(monthWrap);\n\n      // 2. Jam cell with micro visual track\n      const hoursCell = document.createElement('td');\n      const hoursWrap = document.createElement('div');\n      hoursWrap.className = 'metric-cell-wrap';\n      const hoursVal = document.createElement('span');\n      hoursVal.className = 'hours-val';\n      hoursVal.textContent = `${item.hours} jam`;\n      hoursWrap.append(hoursVal);\n      if (item.hours > 0) {\n        const barTrack = document.createElement('span');\n        barTrack.className = 'mini-bar-track';\n        const barFill = document.createElement('span');\n        barFill.className = 'mini-bar-fill';\n        barFill.style.width = `${Math.min(100, Math.round((item.hours / maxHours) * 100))}%`;\n        barTrack.append(barFill);\n        hoursWrap.append(barTrack);\n      }\n      hoursCell.append(hoursWrap);\n\n      // 3. Hari cell with pill\n      const daysCell = document.createElement('td');\n      const daysPill = document.createElement('span');\n      daysPill.className = item.teaching_days > 0 ? 'days-pill' : 'days-pill zero';\n      daysPill.textContent = String(item.teaching_days);\n      daysCell.append(daysPill);\n\n      // 4. Gaji cell with highlight\n      const payCell = document.createElement('td');\n      const payTag = document.createElement('span');\n      payTag.className = Number(item.pay_minor) > 0 ? 'pay-highlight' : 'pay-zero';\n      payTag.textContent = money(item.pay_minor);\n      payCell.append(payTag);\n\n      row.append(monthCell, hoursCell, daysCell, payCell);\n      rows.append(row);\n    }\n\n    const yearRows = $('#year-rows');\n    yearRows.replaceChildren();\n    for (const item of years) {\n      const row = document.createElement('tr');\n      const yearCell = document.createElement('td');\n      const strong = document.createElement('strong');\n      strong.textContent = `Tahun ${item.year}`;\n      yearCell.append(strong);\n      const hoursCell = document.createElement('td');\n      hoursCell.textContent = `${item.hours} jam`;\n      const daysCell = document.createElement('td');\n      const daysPill = document.createElement('span');\n      daysPill.className = 'days-pill';\n      daysPill.textContent = String(item.teaching_days);\n      daysCell.append(daysPill);\n      const payCell = document.createElement('td');\n      const payTag = document.createElement('span');\n      payTag.className = 'pay-highlight';\n      payTag.textContent = money(item.pay_minor);\n      payCell.append(payTag);\n      row.append(yearCell, hoursCell, daysCell, payCell);\n      yearRows.append(row);\n    }\n  }\n  async function load() {\n    try {\n      const response = await fetchImpl('/overview.json', { cache: 'no-store' });\n      if (response.status === 423) { window.location.replace('/unlock'); return; }\n      if (response.status === 401) { window.location.replace('/login'); return; }\n      if (!response.ok) throw Error('source');\n      const data = await response.json();\n      if (data.state === 'connected' || data.state === 'stale') showSummary(data);\n      else showConnection(data.state === 'needs_reconnect' ? 'Koneksi MySalary perlu dihubungkan kembali.' : 'Belum terhubung ke MySalary.');\n    } catch {\n      $('#load-status').textContent = 'Ringkasan belum tersedia. Periksa koneksi lalu muat ulang.';\n      const skeleton = $('#skeleton-panel');\n      if (skeleton) skeleton.hidden = true;\n    }\n  }\n  $('#connect-form').addEventListener('submit', async event => {\n    event.preventDefault(); if (connecting) return;\n    connecting = true; $('#connect-button').disabled = true; $('#connect-status').textContent = 'Menghubungkan…';\n    const email = $('#source-email').value.trim();\n    const password = $('#source-password').value;\n    $('#source-password').value = '';\n    try {\n      const configResponse = await fetchImpl('/connector/config', { cache: 'no-store' });\n      if (configResponse.status === 401) { window.location.replace('/login'); return; }\n      if (!configResponse.ok) throw Error('config');\n      const { apiKey } = await configResponse.json();\n      const auth = await fetchImpl(`https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=${encodeURIComponent(apiKey)}`, {\n        method: 'POST', headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ email, password, returnSecureToken: true }), cache: 'no-store'\n      });\n      if (!auth.ok) throw Error('signin');\n      const { idToken, refreshToken } = await auth.json();\n      const linked = await fetchImpl('/connector/connect', post({ idToken, refreshToken }));\n      if (linked.status === 401) { window.location.replace('/login'); return; }\n      if (!linked.ok) throw Error('connect');\n      await load();\n    } catch { $('#connect-status').textContent = 'Gagal menghubungkan. Periksa akun MySalary dan coba lagi.'; }\n    finally { connecting = false; $('#connect-button').disabled = false; }\n  });\n  $('#disconnect-button').addEventListener('click', async () => {\n    $('#disconnect-button').disabled = true;\n    try {\n      const response = await fetchImpl('/connector/disconnect', post({}));\n      if (response.status === 423) { window.location.replace('/unlock'); return; }\n      if (response.status === 401) { window.location.replace('/login'); return; }\n      if (!response.ok) throw Error('disconnect');\n      showConnection('Koneksi terputus.');\n    } catch { $('#sync-time').textContent = 'Belum dapat memutus koneksi. Coba lagi.'; }\n    finally { $('#disconnect-button').disabled = false; }\n  });\n  $('#logout-form').addEventListener('submit', async event => {\n    event.preventDefault(); $('#summary-panel').hidden = true; $('#connect-panel').hidden = true;\n    try { await fetchImpl('/auth/logout', post({})); } finally { window.location.replace('/login'); }\n  });\n  window.addEventListener('pagehide', () => { $('#summary-panel').hidden = true; });\n  return { ready: load() };\n}\nif (typeof document !== 'undefined') mount();\n",
  "./money.html": "<!doctype html>\n<html lang=\"id\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Money Management · CHARISNA</title><link rel=\"stylesheet\" href=\"/styles.css\"><link rel=\"stylesheet\" href=\"/money.css\"><script type=\"module\" src=\"/money.mjs\"></script></head>\n<body><a class=\"skip\" href=\"#main\">Lewati ke ringkasan</a><header class=\"topbar\"><a class=\"brand\" href=\"/\"><span class=\"brand-mark\" aria-hidden=\"true\">C</span><span>CHARISNA <small>SUPERAPP</small></span></a><div class=\"identity\"><span class=\"role\">Pemilik</span><a class=\"button secondary\" href=\"/security\">Keamanan</a></div></header>\n<main id=\"main\" class=\"live-main\"><nav class=\"source-tabs\" aria-label=\"Sumber data\"><a class=\"button secondary\" href=\"/\">Teaching Pay Audit</a><a class=\"button primary\" href=\"/money\" aria-current=\"page\">Money Management</a><a class=\"button secondary\" href=\"/pos\">Bumi Makmur POS</a><a class=\"button secondary\" href=\"/kost\">CHARISNA KOST</a></nav><div class=\"page-heading\"><div><p class=\"eyebrow\">BERANDA PEMILIK</p><h1>Money Management<span class=\"title-dot\">.</span></h1><p class=\"subtitle\">Ringkasan tiap akun keuangan dalam brankas Anda.</p></div></div>\n<div class=\"demo-note\"><span class=\"note-icon\" aria-hidden=\"true\">i</span><p>Saldo bersih, pemasukan, dan pengeluaran ditampilkan per akun. Mata uang berbeda tidak dijumlahkan.</p></div><p id=\"money-status\" role=\"status\" class=\"field-hint\" style=\"margin-bottom:14px\">Memuat ringkasan…</p>\n<div id=\"money-skeleton\" class=\"skeleton-panel businesses\" aria-hidden=\"true\">\n  <div class=\"section-heading\"><span class=\"skeleton skeleton-title\" style=\"width:190px\"></span><span class=\"skeleton skeleton-badge\"></span></div>\n  <div class=\"business-grid live-stats\">\n    <div class=\"business-card\"><span class=\"skeleton skeleton-title\" style=\"width:130px;height:18px\"></span><span class=\"skeleton skeleton-text\" style=\"width:90px\"></span><span class=\"skeleton skeleton-value\" style=\"width:65%\"></span><span class=\"skeleton skeleton-text\" style=\"width:110px\"></span><span class=\"skeleton skeleton-value\" style=\"width:60%\"></span></div>\n    <div class=\"business-card\"><span class=\"skeleton skeleton-title\" style=\"width:130px;height:18px\"></span><span class=\"skeleton skeleton-text\" style=\"width:90px\"></span><span class=\"skeleton skeleton-value\" style=\"width:65%\"></span><span class=\"skeleton skeleton-text\" style=\"width:110px\"></span><span class=\"skeleton skeleton-value\" style=\"width:60%\"></span></div>\n  </div>\n</div>\n<section id=\"money-connect\" class=\"login-card live-panel\" hidden aria-labelledby=\"money-connect-title\"><p class=\"eyebrow\">SAMBUNGKAN SUMBER</p><h2 id=\"money-connect-title\">Hubungkan Money Management</h2><p>1. Buat kode di sini. 2. Buka Money Management dan masukkan kode pada Pengaturan. Brankas harus terbuka dan akun cloud sudah masuk.</p><button id=\"money-pair\" class=\"button primary\" type=\"button\">Buat kode penghubung</button><p id=\"money-code\" role=\"status\" aria-live=\"polite\"></p><p class=\"scope-note\">Kode berlaku 10 menit. PIN dan isi transaksi tidak dikirim.</p></section>\n<section id=\"money-summary\" class=\"businesses\" hidden aria-labelledby=\"money-summary-title\"><div class=\"section-heading\"><h2 id=\"money-summary-title\">Akun keuangan</h2><span id=\"money-quality\" class=\"badge\"></span></div><p id=\"money-month\" class=\"scope-note\"></p><div id=\"money-profiles\" class=\"business-grid live-stats\"></div><p id=\"money-time\" class=\"scope-note\"></p><p class=\"scope-note\">Saldo bersih memperhitungkan aset dan kewajiban. Pemasukan dan pengeluaran hanya bulan berjalan; transfer tidak dihitung.</p><button id=\"money-disconnect\" class=\"button secondary\" type=\"button\">Putuskan Money Management dan hapus ringkasan</button></section>\n<footer><span>CHARISNA SuperApp</span><span>Ringkasan tersimpan · khusus pemilik</span></footer></main></body></html>\n",
  "./money-ui.mjs": "const $=id=>document.getElementById(id);\nconst post=()=>({method:'POST',headers:{'Content-Type':'application/json'},body:'{}',cache:'no-store'});\nconst format=(minor,currency,scale)=>minor===null?'Tidak tersedia':new Intl.NumberFormat('id-ID',{style:'currency',currency}).format(Number(minor)/10**scale);\nconst go=res=>{if(res.status===401)location.replace('/login');else if(res.status===423)location.replace('/unlock');};\nasync function load(){\n  try{\n    const res=await fetch('/money/overview.json',{cache:'no-store'});go(res);if(!res.ok)throw Error();\n    const data=await res.json();$('money-status').hidden=true;\n    const sk=$('money-skeleton');if(sk)sk.hidden=true;\n    const connected=['connected','stale'].includes(data.state);\n    $('money-connect').hidden=connected;$('money-summary').hidden=!connected;\n    if(connected)$('money-summary').classList.add('fade-in');else $('money-connect').classList.add('fade-in');\n    if(!connected){$('money-code').textContent=data.state==='needs_reconnect'?'Koneksi perlu dibuat ulang.':'Belum terhubung.';return;}\n    $('money-quality').textContent=data.state==='stale'?'Data tertunda':'Ringkasan tersimpan';\n    $('money-quality').className=`badge ${data.state==='stale'?'stale':'verified'}`;\n    $('money-month').textContent=`Bulan: ${data.snapshot.month}`;\n    $('money-time').textContent=`Diterima ${new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(data.received_at))} WIB`;\n    const cards=data.snapshot.profiles.map(p=>{\n      const article=document.createElement('article');article.className='business-card';\n      const title=document.createElement('h3');title.textContent=p.name;article.append(title);\n      for(const [label,key] of [['Saldo bersih','balance_minor'],['Pemasukan bulan ini','income_minor'],['Pengeluaran bulan ini','expense_minor']]){\n        const caption=document.createElement('p');caption.className='metric-label';caption.textContent=label;article.append(caption);\n        const value=document.createElement('p');value.className='money-amount';value.textContent=format(p[key],p.currency,p.scale);article.append(value);\n      }\n      if(p.quality!=='complete'){const note=document.createElement('p');note.className='scope-note';note.textContent='Sebagian nilai tidak tersedia karena kurs mata uang belum ada.';article.append(note);}\n      return article;\n    });\n    $('money-profiles').replaceChildren(...cards);\n  }catch{\n    $('money-status').textContent='Ringkasan belum tersedia. Coba muat ulang.';\n    const sk=$('money-skeleton');if(sk)sk.hidden=true;\n  }\n}\n$('money-pair').addEventListener('click',async()=>{\n  $('money-pair').disabled=true;\n  try{const res=await fetch('/money/pair',post());go(res);if(!res.ok)throw Error();const data=await res.json();$('money-code').textContent=`Kode: ${data.code} · berlaku 10 menit`;}\n  catch{$('money-code').textContent='Gagal membuat kode. Coba lagi.';}\n  finally{$('money-pair').disabled=false;}\n});\n$('money-disconnect').addEventListener('click',async()=>{\n  if(!confirm('Hapus ringkasan dan putuskan koneksi Money Management?'))return;\n  $('money-disconnect').disabled=true;\n  try{const res=await fetch('/money/disconnect',post());go(res);if(!res.ok)throw Error();await load();}\n  catch{$('money-time').textContent='Gagal memutus koneksi. Coba lagi.';}\n  finally{$('money-disconnect').disabled=false;}\n});\nwindow.addEventListener('pagehide',()=>{$('money-profiles').replaceChildren();$('money-code').textContent='';});\nload();\n",
  "./pos.html": "<!doctype html>\n<html lang=\"id\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Bumi Makmur POS · CHARISNA</title><link rel=\"stylesheet\" href=\"/styles.css\"><link rel=\"stylesheet\" href=\"/money.css\"><script type=\"module\" src=\"/pos.mjs\"></script></head>\n<body><a class=\"skip\" href=\"#main\">Lewati ke ringkasan</a><header class=\"topbar\"><a class=\"brand\" href=\"/\"><span class=\"brand-mark\" aria-hidden=\"true\">C</span><span>CHARISNA <small>SUPERAPP</small></span></a><div class=\"identity\"><span class=\"role\">Pemilik</span><a class=\"button secondary\" href=\"/security\">Keamanan</a></div></header>\n<main id=\"main\" class=\"live-main\"><nav class=\"source-tabs\" aria-label=\"Sumber data\"><a class=\"button secondary\" href=\"/\">Teaching Pay Audit</a><a class=\"button secondary\" href=\"/money\">Money Management</a><a class=\"button primary\" href=\"/pos\" aria-current=\"page\">Bumi Makmur POS</a><a class=\"button secondary\" href=\"/kost\">CHARISNA KOST</a></nav><div class=\"page-heading\"><div><p class=\"eyebrow\">BERANDA PEMILIK</p><h1>Bumi Makmur POS<span class=\"title-dot\">.</span></h1><p class=\"subtitle\">Ringkasan usaha per cabang, bulan berjalan.</p></div></div>\n<div class=\"demo-note\"><span class=\"note-icon\" aria-hidden=\"true\">i</span><p>Omzet bersih memperhitungkan refund dan transaksi batal. Laba adalah perkiraan setelah HPP dan beban tercatat; bukan saldo kas.</p></div><p id=\"pos-status\" role=\"status\" class=\"field-hint\" style=\"margin-bottom:14px\">Memuat ringkasan…</p>\n<div id=\"pos-skeleton\" class=\"skeleton-panel businesses\" aria-hidden=\"true\">\n  <div class=\"section-heading\"><span class=\"skeleton skeleton-title\" style=\"width:200px\"></span><span class=\"skeleton skeleton-badge\"></span></div>\n  <div class=\"business-grid live-stats\">\n    <div class=\"business-card\"><span class=\"skeleton skeleton-title\" style=\"width:140px;height:18px\"></span><span class=\"skeleton skeleton-text\" style=\"width:110px\"></span><span class=\"skeleton skeleton-value\" style=\"width:70%\"></span><span class=\"skeleton skeleton-text\" style=\"width:90px\"></span><span class=\"skeleton skeleton-value\" style=\"width:40%\"></span></div>\n    <div class=\"business-card\"><span class=\"skeleton skeleton-title\" style=\"width:140px;height:18px\"></span><span class=\"skeleton skeleton-text\" style=\"width:110px\"></span><span class=\"skeleton skeleton-value\" style=\"width:70%\"></span><span class=\"skeleton skeleton-text\" style=\"width:90px\"></span><span class=\"skeleton skeleton-value\" style=\"width:40%\"></span></div>\n  </div>\n</div>\n<section id=\"pos-connect\" class=\"login-card live-panel\" hidden aria-labelledby=\"pos-connect-title\"><p class=\"eyebrow\">SAMBUNGKAN SUMBER</p><h2 id=\"pos-connect-title\">Hubungkan Bumi Makmur POS</h2><p>Buat kode di sini. Masukkan kode di POS pada Pengaturan Sistem → CHARISNA SuperApp. Gunakan akun Owner saat cloud sudah sinkron.</p><button id=\"pos-pair\" class=\"button primary\" type=\"button\">Buat kode penghubung</button><p id=\"pos-code\" role=\"status\" aria-live=\"polite\"></p><p class=\"scope-note\">Kode berlaku 10 menit. Detail transaksi dan kredensial Firebase tidak dikirim.</p></section>\n<section id=\"pos-summary\" class=\"businesses\" hidden aria-labelledby=\"pos-summary-title\"><div class=\"section-heading\"><h2 id=\"pos-summary-title\">Cabang Bumi Makmur</h2><span id=\"pos-quality\" class=\"badge\"></span></div><p id=\"pos-month\" class=\"scope-note\"></p><div id=\"pos-branches\" class=\"business-grid live-stats\"></div><p id=\"pos-time\" class=\"scope-note\"></p><p class=\"scope-note\">Saat POS ditutup, ringkasan terakhir tetap terlihat. Buka POS dan tunggu sinkronisasi cloud untuk memperbarui angka.</p><button id=\"pos-disconnect\" class=\"button secondary\" type=\"button\">Putuskan POS dan hapus ringkasan</button></section>\n<footer><span>CHARISNA SuperApp</span><span>Ringkasan tersimpan · khusus pemilik</span></footer></main></body></html>\n",
  "./pos-ui.mjs": "const $=id=>document.getElementById(id);\nconst post=()=>({method:'POST',headers:{'Content-Type':'application/json'},body:'{}',cache:'no-store'});\nconst rupiah=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(value));\nconst guard=res=>{if(res.status===401)location.replace('/login');else if(res.status===423)location.replace('/unlock');};\nasync function load(){\n  try{\n    const res=await fetch('/pos/overview.json',{cache:'no-store'});guard(res);if(!res.ok)throw Error();\n    const data=await res.json();$('pos-status').hidden=true;\n    const sk=$('pos-skeleton');if(sk)sk.hidden=true;\n    const connected=['connected','stale'].includes(data.state);\n    $('pos-connect').hidden=connected;$('pos-summary').hidden=!connected;\n    if(connected)$('pos-summary').classList.add('fade-in');else $('pos-connect').classList.add('fade-in');\n    if(!connected){$('pos-code').textContent=data.state==='needs_reconnect'?'Koneksi perlu dibuat ulang.':'Belum terhubung.';return;}\n    $('pos-quality').textContent=data.state==='stale'?'Data tertunda':'Ringkasan tersimpan';\n    $('pos-quality').className=`badge ${data.state==='stale'?'stale':'verified'}`;\n    $('pos-month').textContent=`Bulan: ${data.snapshot.month}`;\n    $('pos-time').textContent=`Diterima ${new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(data.received_at))} WIB`;\n    const cards=data.snapshot.branches.map(branch=>{\n      const card=document.createElement('article');card.className='business-card';\n      const title=document.createElement('h3');title.textContent=branch.name;card.append(title);\n      for(const [label,value] of [['Omzet bersih bulan ini',rupiah(branch.revenue_idr)],['Jumlah transaksi',String(branch.transactions)],['Laba perkiraan bulan ini',rupiah(branch.profit_estimate_idr)]]){\n        const caption=document.createElement('p');caption.className='metric-label';caption.textContent=label;\n        const amount=document.createElement('p');amount.className='money-amount';amount.textContent=value;\n        card.append(caption,amount);\n      }\n      return card;\n    });\n    $('pos-branches').replaceChildren(...cards);\n  }catch{\n    $('pos-status').hidden=false;$('pos-status').textContent='Ringkasan belum tersedia. Coba muat ulang.';\n    const sk=$('pos-skeleton');if(sk)sk.hidden=true;\n  }\n}\n$('pos-pair').addEventListener('click',async()=>{\n  $('pos-pair').disabled=true;\n  try{const res=await fetch('/pos/pair',post());guard(res);if(!res.ok)throw Error();const data=await res.json();$('pos-code').textContent=`Kode: ${data.code} · berlaku 10 menit`;}\n  catch{$('pos-code').textContent='Gagal membuat kode. Coba lagi.';}\n  finally{$('pos-pair').disabled=false;}\n});\n$('pos-disconnect').addEventListener('click',async()=>{\n  if(!confirm('Hapus ringkasan dan putuskan koneksi Bumi Makmur POS?'))return;\n  $('pos-disconnect').disabled=true;\n  try{const res=await fetch('/pos/disconnect',post());guard(res);if(!res.ok)throw Error();await load();}\n  catch{$('pos-time').textContent='Gagal memutus koneksi. Coba lagi.';}\n  finally{$('pos-disconnect').disabled=false;}\n});\nwindow.addEventListener('pagehide',()=>{$('pos-branches').replaceChildren();$('pos-code').textContent='';});\nload();\n",
  "./kost.html": "<!doctype html>\n<html lang=\"id\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CHARISNA KOST · SuperApp</title><link rel=\"stylesheet\" href=\"/styles.css\"><link rel=\"stylesheet\" href=\"/money.css\"><script type=\"module\" src=\"/kost.mjs\"></script></head>\n<body><a class=\"skip\" href=\"#main\">Lewati ke ringkasan</a><header class=\"topbar\"><a class=\"brand\" href=\"/\"><span class=\"brand-mark\" aria-hidden=\"true\">C</span><span>CHARISNA <small>SUPERAPP</small></span></a><div class=\"identity\"><span class=\"role\">Pemilik</span><a class=\"button secondary\" href=\"/security\">Keamanan</a></div></header>\n<main id=\"main\" class=\"live-main\"><nav class=\"source-tabs\" aria-label=\"Sumber data\"><a class=\"button secondary\" href=\"/\">Teaching Pay Audit</a><a class=\"button secondary\" href=\"/money\">Money Management</a><a class=\"button secondary\" href=\"/pos\">Bumi Makmur POS</a><a class=\"button primary\" href=\"/kost\" aria-current=\"page\">CHARISNA KOST</a></nav><div class=\"page-heading\"><div><p class=\"eyebrow\">BERANDA PEMILIK</p><h1>CHARISNA KOST<span class=\"title-dot\">.</span></h1><p class=\"subtitle\">Okupansi dan tagihan per properti.</p></div></div>\n<div class=\"demo-note\"><span class=\"note-icon\" aria-hidden=\"true\">i</span><p>Ringkasan berasal dari data lokal perangkat Owner yang terhubung. Cloud KOST masih ditransfer manual. Tanggal snapshot terlihat di bawah.</p></div><p id=\"kost-status\" role=\"status\" class=\"field-hint\" style=\"margin-bottom:14px\">Memuat ringkasan…</p>\n<div id=\"kost-skeleton\" class=\"skeleton-panel businesses\" aria-hidden=\"true\">\n  <div class=\"section-heading\"><span class=\"skeleton skeleton-title\" style=\"width:160px\"></span><span class=\"skeleton skeleton-badge\"></span></div>\n  <div class=\"business-grid live-stats\">\n    <div class=\"business-card\"><span class=\"skeleton skeleton-title\" style=\"width:130px;height:18px\"></span><span class=\"skeleton skeleton-text\" style=\"width:90px\"></span><span class=\"skeleton skeleton-value\" style=\"width:50%\"></span><span class=\"skeleton skeleton-text\" style=\"width:120px\"></span><span class=\"skeleton skeleton-value\" style=\"width:65%\"></span></div>\n    <div class=\"business-card\"><span class=\"skeleton skeleton-title\" style=\"width:130px;height:18px\"></span><span class=\"skeleton skeleton-text\" style=\"width:90px\"></span><span class=\"skeleton skeleton-value\" style=\"width:50%\"></span><span class=\"skeleton skeleton-text\" style=\"width:120px\"></span><span class=\"skeleton skeleton-value\" style=\"width:65%\"></span></div>\n  </div>\n</div>\n<section id=\"kost-connect\" class=\"login-card live-panel\" hidden aria-labelledby=\"kost-connect-title\"><p class=\"eyebrow\">SAMBUNGKAN SUMBER</p><h2 id=\"kost-connect-title\">Hubungkan CHARISNA KOST</h2><p>Buat kode di sini. Buka aplikasi KOST sebagai Owner, lalu masukkan kode pada Cloud & Akun → CHARISNA SuperApp.</p><button id=\"kost-pair\" class=\"button primary\" type=\"button\">Buat kode penghubung</button><p id=\"kost-code\" role=\"status\" aria-live=\"polite\"></p><p class=\"scope-note\">Kode berlaku 10 menit. Data bawaan boleh dikirim dengan label contoh. Identitas penghuni, foto, dan detail tagihan tidak dikirim.</p></section>\n<section id=\"kost-summary\" class=\"businesses\" hidden aria-labelledby=\"kost-summary-title\"><div class=\"section-heading\"><h2 id=\"kost-summary-title\">Properti</h2><span id=\"kost-quality\" class=\"badge\"></span></div><p id=\"kost-demo-note\" class=\"scope-note\" hidden>Data contoh bawaan KOST. Angka ini belum mewakili usaha nyata. Label hilang setelah semua data contoh diganti.</p><p id=\"kost-month\" class=\"scope-note\"></p><div id=\"kost-properties\" class=\"business-grid live-stats\"></div><p id=\"kost-unassigned\" class=\"scope-note\"></p><p id=\"kost-time\" class=\"scope-note\"></p><p class=\"scope-note\">Pembayaran diterima dihitung dari tagihan berstatus LUNAS dengan tanggal bayar bulan ini. Tagihan belum lunas mencakup semua periode.</p><button id=\"kost-disconnect\" class=\"button secondary\" type=\"button\">Putuskan KOST dan hapus ringkasan</button></section>\n<footer><span>CHARISNA SuperApp</span><span>Ringkasan tersimpan · khusus pemilik</span></footer></main></body></html>\n",
  "./kost-ui.mjs": "const $=id=>document.getElementById(id);\nconst post=()=>({method:'POST',headers:{'Content-Type':'application/json'},body:'{}',cache:'no-store'});\nconst rupiah=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(value));\nconst guard=res=>{if(res.status===401)location.replace('/login');else if(res.status===423)location.replace('/unlock');};\nasync function load(){\n  try{\n    const res=await fetch('/kost/overview.json',{cache:'no-store'});guard(res);if(!res.ok)throw Error();\n    const data=await res.json();$('kost-status').hidden=true;\n    const sk=$('kost-skeleton');if(sk)sk.hidden=true;\n    const connected=['connected','stale'].includes(data.state);\n    $('kost-connect').hidden=connected;$('kost-summary').hidden=!connected;\n    if(connected)$('kost-summary').classList.add('fade-in');else $('kost-connect').classList.add('fade-in');\n    if(!connected){$('kost-properties').replaceChildren();$('kost-code').textContent=data.state==='needs_reconnect'?'Koneksi perlu dibuat ulang.':'Belum terhubung.';return;}\n    const isDemo=data.snapshot.is_demo===true;\n    $('kost-quality').textContent=isDemo?data.state==='stale'?'Data contoh · tertunda':'Data contoh':data.state==='stale'?'Data tertunda':'Snapshot lokal';\n    $('kost-quality').className=`badge ${isDemo||data.state==='stale'?'stale':'verified'}`;\n    $('kost-demo-note').hidden=!isDemo;\n    $('kost-month').textContent=`Bulan pembayaran: ${data.snapshot.month}`;\n    $('kost-time').textContent=`Diterima ${new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(data.received_at))} WIB`;\n    $('kost-unassigned').textContent=data.snapshot.unassigned_bills?`${data.snapshot.unassigned_bills} tagihan belum dapat dipetakan ke properti. Angkanya tidak masuk kartu di bawah.`:'';\n    const cards=data.snapshot.properties.map(property=>{\n      const card=document.createElement('article');card.className='business-card';\n      const title=document.createElement('h3');title.textContent=property.name;card.append(title);\n      for(const [label,value] of [['Kamar terisi',`${property.occupied_rooms} / ${property.total_rooms}`],['Pembayaran diterima bulan ini',rupiah(property.paid_this_month_idr)],['Tagihan belum lunas',rupiah(property.unpaid_bills_idr)]]){\n        const caption=document.createElement('p');caption.className='metric-label';caption.textContent=label;\n        const amount=document.createElement('p');amount.className='money-amount';amount.textContent=value;\n        card.append(caption,amount);\n      }\n      return card;\n    });\n    $('kost-properties').replaceChildren(...cards);\n  }catch{\n    $('kost-summary').hidden=true;$('kost-properties').replaceChildren();$('kost-demo-note').hidden=true;$('kost-status').hidden=false;$('kost-status').textContent='Ringkasan belum tersedia. Coba muat ulang.';\n    const sk=$('kost-skeleton');if(sk)sk.hidden=true;\n  }\n}\n$('kost-pair').addEventListener('click',async()=>{\n  $('kost-pair').disabled=true;\n  try{const res=await fetch('/kost/pair',post());guard(res);if(!res.ok)throw Error();const data=await res.json();$('kost-code').textContent=`Kode: ${data.code} · berlaku 10 menit`;}\n  catch{$('kost-code').textContent='Gagal membuat kode. Coba lagi.';}\n  finally{$('kost-pair').disabled=false;}\n});\n$('kost-disconnect').addEventListener('click',async()=>{\n  if(!confirm('Hapus ringkasan dan putuskan koneksi CHARISNA KOST?'))return;\n  $('kost-disconnect').disabled=true;\n  try{const res=await fetch('/kost/disconnect',post());guard(res);if(!res.ok)throw Error();await load();}\n  catch{$('kost-time').textContent='Gagal memutus koneksi. Coba lagi.';}\n  finally{$('kost-disconnect').disabled=false;}\n});\nwindow.addEventListener('pagehide',()=>{$('kost-properties').replaceChildren();$('kost-code').textContent='';});\nload();\n",
  "../public/styles.css": ":root{\n  --ink:#142826;\n  --muted:#576b66;\n  --line:#dfe6e1;\n  --line-light:#eef3ef;\n  --paper:#f7f9f7;\n  --white:#ffffff;\n  --teal:#195244;\n  --teal-hover:#123e33;\n  --teal-surface:#edf5f1;\n  --teal-border:#c5d9ce;\n  --rust:#a03828;\n  --rust-surface:#fcf1ee;\n  --amber:#885d13;\n  --amber-surface:#fcf6e8;\n  --radius-sm:8px;\n  --radius-md:14px;\n  --radius:16px;\n  --radius-lg:22px;\n  --shadow-subtle:0 1px 3px rgba(20,40,38,0.04);\n  --shadow-card:0 2px 8px -2px rgba(20,40,38,0.05),0 1px 3px rgba(20,40,38,0.03);\n  --shadow-hover:0 10px 28px -4px rgba(20,40,38,0.09),0 2px 6px rgba(20,40,38,0.04);\n  --shadow-dialog:0 24px 64px -8px rgba(16,44,38,0.22);\n}\n*{box-sizing:border-box}\nbody{\n  margin:0;\n  background:var(--paper);\n  color:var(--ink);\n  font:15px/1.55 -apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif;\n  -webkit-font-smoothing:antialiased;\n  -moz-osx-font-smoothing:grayscale;\n}\nbutton,a{-webkit-tap-highlight-color:transparent}\nbutton{font:inherit;cursor:pointer}\na{color:inherit}\nbutton:focus-visible,a:focus-visible,input:focus-visible{\n  outline:2px solid var(--teal);\n  outline-offset:3px;\n}\n.skip{\n  position:absolute;\n  top:-70px;\n  background:var(--white);\n  padding:12px 18px;\n  z-index:100;\n  border-radius:0 0 var(--radius-sm) var(--radius-sm);\n  box-shadow:var(--shadow-card);\n  font-weight:600;\n  color:var(--teal);\n  transition:top 0.15s ease;\n}\n.skip:focus{top:0}\n.topbar{\n  height:84px;\n  padding:0 max(24px,calc((100% - 1160px)/2));\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  border-bottom:1px solid var(--line);\n  background:var(--white);\n  transition:border-color 0.2s ease,box-shadow 0.2s ease;\n}\n.brand{\n  display:flex;\n  align-items:center;\n  gap:12px;\n  text-decoration:none;\n  font-weight:700;\n  letter-spacing:1.2px;\n  font-size:17px;\n  line-height:1.2;\n  transition:transform 0.15s ease;\n}\n.brand:hover{transform:translateY(-1px)}\n.brand small{\n  display:block;\n  font-size:9.5px;\n  letter-spacing:3px;\n  font-weight:600;\n  color:var(--muted);\n  margin-top:4px;\n}\n.brand-mark{\n  display:grid;\n  place-items:center;\n  background:linear-gradient(145deg,var(--teal),var(--teal-hover));\n  color:var(--white);\n  width:38px;\n  height:42px;\n  border-radius:12px 12px 4px 12px;\n  font:26px Georgia,serif;\n  box-shadow:0 3px 8px rgba(25,82,68,0.22);\n  transition:transform 0.2s cubic-bezier(0.2,0.8,0.2,1),box-shadow 0.2s ease;\n}\n.brand:hover .brand-mark{\n  transform:scale(1.04);\n  box-shadow:0 5px 14px rgba(25,82,68,0.28);\n}\n.identity{display:flex;align-items:center;gap:16px;font-size:13px}\n.demo-label{\n  padding:5px 12px;\n  border:1px solid var(--teal-border);\n  border-radius:20px;\n  color:var(--teal);\n  font-weight:600;\n  font-size:12px;\n  background:var(--teal-surface);\n  letter-spacing:0.2px;\n}\n.role{\n  border-left:1px solid var(--line);\n  padding-left:16px;\n  color:var(--muted);\n  font-weight:500;\n}\nmain{max-width:1160px;margin:auto;padding:44px 24px 0}\n.page-heading{\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  gap:24px;\n  margin-bottom:28px;\n}\n.eyebrow{\n  font-size:10px;\n  letter-spacing:1.8px;\n  font-weight:700;\n  color:var(--muted);\n  margin:0 0 8px;\n  text-transform:uppercase;\n}\nh1{\n  font:normal clamp(30px,3.2vw,42px)/1.18 Georgia,\"Newsreader\",\"Times New Roman\",serif;\n  letter-spacing:-1.2px;\n  margin:0 0 10px;\n  color:var(--ink);\n}\n.title-dot{color:var(--teal)}\n.subtitle{color:var(--muted);font-size:14px;margin:0;line-height:1.55}\n.period{\n  font-size:13px;\n  border:1px solid var(--line);\n  border-radius:12px;\n  padding:12px 16px;\n  white-space:nowrap;\n  background:var(--white);\n  box-shadow:var(--shadow-subtle);\n  margin:0;\n  transition:box-shadow 0.2s ease;\n}\n.period small{\n  font-size:10px;\n  color:var(--muted);\n  display:block;\n  padding-left:17px;\n  margin-top:3px;\n}\n.period-dot{\n  display:inline-block;\n  width:7px;\n  height:7px;\n  background:var(--teal);\n  border-radius:50%;\n  margin:0 10px 1px 0;\n  box-shadow:0 0 0 3px rgba(25,82,68,0.15);\n}\n.demo-note{\n  display:flex;\n  align-items:center;\n  gap:12px;\n  background:var(--teal-surface);\n  border:1px solid var(--teal-border);\n  padding:12px 16px;\n  border-radius:var(--radius-sm);\n  margin-bottom:32px;\n  font-size:12.5px;\n  color:var(--teal-hover);\n  line-height:1.5;\n}\n.demo-note p{margin:0}\n.note-icon{\n  border:1.5px solid var(--teal);\n  border-radius:50%;\n  width:18px;\n  height:18px;\n  display:grid;\n  place-items:center;\n  font-size:11px;\n  font-family:Georgia,serif;\n  font-weight:700;\n  flex-shrink:0;\n}\n.section-heading{\n  display:flex;\n  align-items:center;\n  gap:12px;\n  justify-content:space-between;\n  margin-bottom:16px;\n}\nh2{\n  font-size:18px;\n  letter-spacing:-0.3px;\n  font-weight:600;\n  margin:0;\n  color:var(--ink);\n}\n.attention .section-heading{justify-content:flex-start}\n.count{\n  font-size:11px;\n  border-radius:20px;\n  background:#e5ebe6;\n  padding:2px 9px;\n  color:var(--muted);\n  font-weight:600;\n}\n.attention-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.attention-card{\n  background:var(--white);\n  border:1px solid #e2d8cd;\n  border-left:4px solid #b76045;\n  border-radius:0 var(--radius-md) var(--radius-md) 0;\n  padding:22px 24px;\n  box-shadow:var(--shadow-card);\n  transition:transform 0.18s cubic-bezier(0.2,0.8,0.2,1),box-shadow 0.18s ease;\n}\n.attention-card:hover{\n  transform:translateY(-2px);\n  box-shadow:var(--shadow-hover);\n}\n.attention-card.incomplete{\n  border-color:#e5dfcf;\n  border-left-color:#b08b37;\n}\n.card-top{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:12px;\n  margin-bottom:12px;\n}\n.card-top h3{font-size:14px;margin:0;font-weight:600}\n.badge{\n  font-size:11px;\n  font-weight:600;\n  border-radius:6px;\n  padding:4px 9px;\n  background:var(--rust-surface);\n  color:var(--rust);\n  white-space:nowrap;\n  display:inline-flex;\n  align-items:center;\n  gap:6px;\n  letter-spacing:0.1px;\n}\n.badge::before{\n  content:\"\";\n  width:5px;\n  height:5px;\n  border-radius:50%;\n  background:currentColor;\n}\n.badge.incomplete,.badge.provisional{\n  color:var(--amber);\n  background:var(--amber-surface);\n}\n.badge.unavailable,.badge.stale{\n  color:var(--muted);\n  background:#ecefe8;\n}\n.badge.verified{\n  color:var(--teal);\n  background:var(--teal-surface);\n}\n.attention-card p{\n  font-size:18px;\n  font-weight:600;\n  letter-spacing:-0.4px;\n  margin:0 0 4px;\n}\n.attention-card .explanation{\n  font-size:12.5px;\n  color:var(--muted);\n  font-weight:400;\n  margin-bottom:16px;\n  letter-spacing:0;\n  line-height:1.55;\n}\n.text-button{\n  border:0;\n  padding:6px 0;\n  background:none;\n  font-size:12px;\n  color:var(--teal);\n  font-weight:700;\n  text-decoration:underline;\n  text-underline-offset:4px;\n  transition:color 0.15s ease,text-underline-offset 0.15s ease;\n}\n.text-button:hover{\n  color:var(--teal-hover);\n  text-underline-offset:6px;\n}\n.text-button span{margin-left:8px;text-decoration:none;display:inline-block;transition:transform 0.15s ease}\n.text-button:hover span{transform:translateX(3px)}\n.businesses{margin-top:36px}\n.section-caption{color:var(--muted);font-size:11.5px}\n.business-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}\n.business-card{\n  border:1px solid var(--line);\n  border-radius:var(--radius);\n  background:var(--white);\n  padding:24px 22px 20px;\n  min-width:0;\n  display:flex;\n  flex-direction:column;\n  box-shadow:var(--shadow-card);\n  transition:transform 0.18s cubic-bezier(0.2,0.8,0.2,1),box-shadow 0.18s ease,border-color 0.18s ease;\n}\n.business-card:hover{\n  transform:translateY(-2px);\n  box-shadow:var(--shadow-hover);\n  border-color:var(--teal-border);\n}\n.business-card .card-top{\n  margin-bottom:24px;\n  align-items:flex-start;\n  gap:6px;\n}\n.business-name{display:flex;align-items:center;gap:10px;font-size:13.5px;font-weight:600}\n.business-icon{\n  width:28px;\n  height:30px;\n  border:1px solid var(--teal-border);\n  border-radius:8px;\n  display:grid;\n  place-items:center;\n  font-size:12px;\n  color:var(--teal);\n  background:var(--teal-surface);\n  flex-shrink:0;\n}\n.metric-label{font-size:12px;color:var(--muted);margin:0 0 8px;font-weight:500}\n.metric-value{\n  font-size:29px;\n  font-weight:600;\n  letter-spacing:-1.1px;\n  line-height:1.25;\n  margin:0 0 8px;\n  font-variant-numeric:tabular-nums;\n  color:var(--ink);\n}\n.metric-context{font-size:11.5px;color:var(--muted);margin:0 0 24px;min-height:34px;line-height:1.5}\n.card-bottom{\n  border-top:1px solid var(--line-light);\n  padding-top:14px;\n  margin-top:auto;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:8px;\n}\n.received{font-size:12px;color:var(--muted)}\n.card-bottom .text-button{font-size:11.5px}\n.scope-note{font-size:11.5px;color:var(--muted);margin-top:14px;line-height:1.6}\n.personal{\n  border:1px solid #d9e1d5;\n  background:linear-gradient(135deg,#edf3e9,#e5ede0);\n  border-radius:var(--radius);\n  margin-top:32px;\n  padding:24px 26px;\n  display:grid;\n  grid-template-columns:1fr auto;\n  gap:8px 20px;\n  box-shadow:var(--shadow-card);\n}\n.personal .eyebrow{font-size:9.5px;color:var(--teal-hover)}\n.personal h2{font:23px Georgia,serif;letter-spacing:-0.5px}\n.personal-copy>p:last-child{font-size:12px;margin:9px 0 0}\n.personal-copy>p span{color:var(--muted)}\n.balance-control{text-align:right;align-self:center}\n.balance{font-size:13px;color:var(--muted);margin:0 0 8px}\n.balance.visible{font-size:25px;letter-spacing:-0.5px;color:var(--ink);font-weight:600}\n.button{\n  border-radius:var(--radius-sm);\n  padding:9px 15px;\n  font-size:12.5px;\n  min-height:40px;\n  font-weight:600;\n  display:inline-flex;\n  align-items:center;\n  justify-content:center;\n  gap:8px;\n  transition:transform 0.15s cubic-bezier(0.2,0.8,0.2,1),box-shadow 0.15s ease,background 0.15s ease,border-color 0.15s ease;\n}\n.button:hover:not(:disabled){\n  transform:translateY(-1px);\n  box-shadow:0 3px 10px rgba(25,82,68,0.14);\n}\n.button:active:not(:disabled){\n  transform:scale(0.98) translateY(0);\n  box-shadow:none;\n}\n.button:disabled{cursor:not-allowed;opacity:.62;filter:none}\n.secondary{\n  border:1px solid #c2d1c5;\n  color:#274d35;\n  background:var(--white);\n  box-shadow:var(--shadow-subtle);\n}\n.secondary:hover:not(:disabled){\n  background:#f5faf6;\n  border-color:var(--teal-border);\n}\n.primary{\n  border:1px solid var(--teal);\n  background:linear-gradient(145deg,var(--teal),var(--teal-hover));\n  color:var(--white);\n  box-shadow:0 2px 6px rgba(25,82,68,0.2);\n}\n.primary:hover:not(:disabled){\n  background:linear-gradient(145deg,var(--teal-hover),#0f342b);\n}\n.privacy-note{grid-column:1/-1;color:var(--muted);font-size:12px;margin:8px 0 0}\nfooter{\n  border-top:1px solid var(--line);\n  margin-top:44px;\n  padding:22px 0;\n  display:flex;\n  justify-content:space-between;\n  gap:12px;\n  color:var(--muted);\n  font-size:11px;\n}\nfooter span:first-child{letter-spacing:1px;text-transform:uppercase;font-weight:600}\ndialog{\n  border:1px solid #d4ded5;\n  border-radius:var(--radius-lg);\n  padding:0;\n  width:min(620px,calc(100% - 32px));\n  max-height:90dvh;\n  color:var(--ink);\n  box-shadow:var(--shadow-dialog);\n}\ndialog::backdrop{background:#12292399;backdrop-filter:blur(2px)}\n.dialog-header{\n  padding:22px 25px 4px;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n}\n.dialog-header .eyebrow{margin:0}\n.close-button{\n  width:36px;\n  height:36px;\n  border:1px solid var(--line);\n  background:var(--paper);\n  border-radius:50%;\n  font-size:22px;\n  line-height:1;\n  display:grid;\n  place-items:center;\n  transition:transform 0.15s ease,background 0.15s ease;\n}\n.close-button:hover{\n  background:#e7ede8;\n  transform:scale(1.06);\n}\n.dialog-body{padding:12px 25px 24px}\n.dialog-body h2{font:30px Georgia,serif;margin:0 0 10px}\n.detail-intro{font-size:13px;color:var(--muted);margin:16px 0 20px}\n.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:18px 0}\n.detail-stat{\n  background:#f4f7f3;\n  border:1px solid var(--line);\n  border-radius:var(--radius-sm);\n  padding:15px;\n}\n.detail-stat span{display:block;font-size:11px;color:var(--muted);margin-bottom:5px}\n.detail-stat strong{font-size:22px;font-weight:600;letter-spacing:-0.5px}\n.detail-stat.alert{background:var(--rust-surface);border-color:#f0d8cb}\n.detail-stat.alert strong{color:var(--rust)}\ndl{font-size:12.5px;margin:20px 0 0}\ndl div{\n  display:flex;\n  justify-content:space-between;\n  gap:15px;\n  padding:10px 0;\n  border-bottom:1px solid var(--line);\n}\ndt{color:var(--muted)}\ndd{margin:0;text-align:right;font-weight:500}\n.detail-note{\n  font-size:12px;\n  line-height:1.7;\n  background:var(--teal-surface);\n  border-radius:var(--radius-sm);\n  padding:14px;\n  margin:18px 0 0;\n}\n.dialog-footer{\n  border-top:1px solid var(--line);\n  padding:17px 25px;\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  gap:16px;\n}\n.dialog-footer p{font-size:10.5px;color:var(--muted);max-width:230px;margin:0}\n#load-status{font-size:14px}\n[hidden]{display:none!important}\n\n/* ======================================================== */\n/* SKELETON SHIMMER & LOADING ANIMATION                     */\n/* ======================================================== */\n@keyframes shimmerWave{\n  0%{background-position:-200% 0}\n  100%{background-position:200% 0}\n}\n.skeleton{\n  background:linear-gradient(90deg,#e8eee9 0%,#f5f9f6 45%,#e8eee9 90%);\n  background-size:200% 100%;\n  animation:shimmerWave 1.6s ease-in-out infinite;\n  border-radius:6px;\n  display:inline-block;\n  color:transparent!important;\n  user-select:none;\n  pointer-events:none;\n}\n.skeleton-text{height:13px;margin-bottom:8px;border-radius:4px}\n.skeleton-title{height:22px;width:60%;margin-bottom:14px;border-radius:6px}\n.skeleton-value{height:34px;width:55%;margin:4px 0 12px;border-radius:8px}\n.skeleton-badge{height:20px;width:95px;border-radius:12px}\n.skeleton-row{height:38px;width:100%;margin-bottom:8px;border-radius:6px}\n.skeleton-panel{display:block;margin-top:20px}\n\n@keyframes fadeInCard{\n  from{opacity:0;transform:translateY(6px)}\n  to{opacity:1;transform:translateY(0)}\n}\n.fade-in{\n  animation:fadeInCard 0.24s cubic-bezier(0.16,1,0.3,1) forwards;\n}\n\n/* ======================================================== */\n/* TABLE HEADER BAR & SCROLL CONTAINER                      */\n/* ======================================================== */\n.table-header-bar{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  margin:32px 0 12px;\n}\n.table-hint-pill{\n  font-size:11px;\n  font-weight:600;\n  color:var(--teal);\n  background:var(--teal-surface);\n  border:1px solid var(--teal-border);\n  padding:3px 10px;\n  border-radius:12px;\n  letter-spacing:0.2px;\n}\n.live-table-scroll{\n  max-height:290px;\n  overflow-y:auto;\n  overflow-x:auto;\n  position:relative;\n  scrollbar-width:thin;\n  scrollbar-color:var(--teal-border) transparent;\n}\n.live-table-scroll thead th{\n  position:sticky;\n  top:0;\n  z-index:3;\n  background:#f8faf8;\n  box-shadow:0 1px 0 var(--line);\n}\n.live-table-scroll::-webkit-scrollbar{\n  width:6px;\n  height:6px;\n}\n.live-table-scroll::-webkit-scrollbar-track{\n  background:#f1f4f1;\n  border-radius:8px;\n}\n.live-table-scroll::-webkit-scrollbar-thumb{\n  background:#bcd0c5;\n  border-radius:8px;\n}\n.live-table-scroll::-webkit-scrollbar-thumb:hover{\n  background:var(--teal);\n}\n\n/* ======================================================== */\n/* RICH ROW MICRO-TOUCHES & VISUAL ENHANCEMENTS            */\n/* ======================================================== */\n.live-table tbody tr:nth-child(even){\n  background:#fafcfa;\n}\n.cell-month-wrap{\n  display:inline-flex;\n  align-items:center;\n  gap:9px;\n}\n.month-name{\n  font-weight:600;\n  color:var(--ink);\n}\n.badge-mini{\n  font-size:10px;\n  font-weight:700;\n  padding:2px 7px;\n  border-radius:10px;\n  letter-spacing:0.3px;\n  text-transform:uppercase;\n}\n.badge-mini.current{\n  background:var(--teal-surface);\n  color:var(--teal);\n  border:1px solid var(--teal-border);\n}\n.row-current{\n  background:#edf6f1!important;\n}\n.row-current .month-name{\n  color:var(--teal-hover);\n  font-weight:700;\n}\n.row-zero{\n  color:var(--muted);\n  opacity:0.82;\n}\n.row-zero .month-name{\n  color:var(--muted);\n  font-weight:400;\n}\n.metric-cell-wrap{\n  display:flex;\n  flex-direction:column;\n  gap:4px;\n}\n.hours-val{\n  font-weight:500;\n}\n.mini-bar-track{\n  width:58px;\n  height:4px;\n  background:#e1e9e3;\n  border-radius:2px;\n  overflow:hidden;\n  display:block;\n}\n.mini-bar-fill{\n  height:100%;\n  background:linear-gradient(90deg,var(--teal),#2c8c76);\n  border-radius:2px;\n  display:block;\n}\n.days-pill{\n  display:inline-block;\n  padding:3px 9px;\n  background:#edf4ef;\n  border-radius:6px;\n  font-size:12px;\n  font-weight:600;\n  color:#1e4b3c;\n  border:1px solid #dbe6df;\n}\n.days-pill.zero{\n  background:transparent;\n  color:var(--muted);\n  font-weight:400;\n  border-color:transparent;\n}\n.pay-highlight{\n  color:#0f4b3b;\n  font-weight:700;\n  background:#e8f4ec;\n  padding:3px 9px;\n  border-radius:6px;\n  display:inline-block;\n  border:1px solid #cce5d6;\n}\n.pay-zero{\n  color:var(--muted);\n  font-weight:400;\n}\n\n/* Accents on Metric Cards */\n.live-stats .business-card{\n  position:relative;\n  overflow:hidden;\n  border-top:3px solid var(--teal);\n}\n.live-stats .business-card:nth-child(2){\n  border-top-color:#277b69;\n}\n.live-stats .business-card:nth-child(3){\n  border-top-color:#9c6c19;\n}\n.live-stats .business-card:nth-child(4){\n  border-top-color:#3b5f7e;\n}\n\n/* ======================================================== */\n/* LOGIN, UNLOCK, & SECURITY CARDS                          */\n/* ======================================================== */\n#logout-form{margin:0}\n.logout-status{margin:0 0 16px;color:var(--rust);font-size:13px}\n.logout-status:empty{display:none}\n.login-main{\n  max-width:1080px;\n  display:grid;\n  grid-template-columns:minmax(0,1fr) minmax(0,440px);\n  gap:64px;\n  align-items:center;\n  padding-top:64px;\n}\n.login-intro h1{\n  font-size:clamp(36px,4.4vw,54px);\n  line-height:1.13;\n  letter-spacing:-1.5px;\n  margin:20px 0;\n}\n.login-intro .subtitle{font-size:16px;max-width:380px;line-height:1.7}\n.login-context{\n  display:flex;\n  align-items:flex-start;\n  gap:12px;\n  border-top:1px solid var(--line);\n  padding-top:24px;\n  margin-top:32px;\n  max-width:390px;\n  color:var(--muted);\n  font-size:13px;\n  line-height:1.55;\n}\n.login-context .note-icon{margin-top:3px}\n.login-context p{margin:0}\n.login-session{\n  font-size:12.5px;\n  color:var(--muted);\n  max-width:390px;\n  line-height:1.7;\n  margin:18px 0 0;\n}\n.login-card{\n  min-width:0;\n  background:var(--white);\n  border:1px solid var(--line);\n  border-radius:var(--radius-lg);\n  padding:34px;\n  box-shadow:var(--shadow-card);\n  transition:box-shadow 0.2s ease;\n}\n.login-card h2{\n  font:30px/1.2 Georgia,serif;\n  letter-spacing:-0.6px;\n  margin:8px 0 14px;\n}\n.login-description{font-size:14px;color:var(--muted);margin:0 0 24px;line-height:1.7}\n.login-card .button{\n  width:100%;\n  min-height:46px;\n  font-size:14px;\n  font-weight:600;\n  border-radius:10px;\n  margin-top:8px;\n}\n.login-divider{height:1px;background:var(--line);margin:24px 0}\n.login-card input{\n  display:block;\n  width:100%;\n  min-height:46px;\n  padding:11px 14px;\n  margin-bottom:18px;\n  border:1px solid #b5c7bc;\n  border-radius:var(--radius-sm);\n  background:var(--white);\n  font:inherit;\n  transition:border-color 0.15s ease,box-shadow 0.15s ease;\n}\n.login-card input:focus{\n  border-color:var(--teal);\n  box-shadow:0 0 0 3px rgba(25,82,68,0.14);\n}\n.login-card details{\n  margin:24px 0 16px;\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:var(--radius-sm);\n  padding:12px 14px;\n  transition:background 0.15s ease;\n}\n.login-card summary{\n  cursor:pointer;\n  font-size:13.5px;\n  font-weight:600;\n  color:var(--ink);\n  line-height:1.6;\n  user-select:none;\n}\n.login-card .field-hint{font-size:13px;margin:12px 0 16px;color:var(--muted)}\n.login-card label{display:block;font-size:13.5px;font-weight:600;margin-bottom:6px;color:var(--ink)}\n.field-hint{font-size:12px;color:var(--muted);margin:8px 0 0;line-height:1.6}\n#code-hint{margin:0 0 12px}\n#login-code{\n  display:block;\n  max-width:100%;\n  width:100%;\n  min-height:52px;\n  border:1px solid #b5c7bc;\n  border-radius:var(--radius-sm);\n  font:24px/1.3 'Segoe UI',Arial,sans-serif;\n  font-variant-numeric:tabular-nums;\n  letter-spacing:0.15em;\n  color:var(--ink);\n  background:#fafbf8;\n  padding:10px 14px;\n  margin:0 0 18px;\n}\n#login-code[aria-invalid=\"true\"]{border-color:var(--rust)}\n.login-status,.login-error{\n  font-size:13px;\n  line-height:1.65;\n  margin:18px 0 0;\n  overflow-wrap:anywhere;\n  padding:10px 14px;\n  border-radius:var(--radius-sm);\n}\n.login-status{color:var(--teal);background:var(--teal-surface);border:1px solid var(--teal-border)}\n.login-error{color:var(--rust);background:var(--rust-surface);border:1px solid #f0d8cb}\n.login-status:empty,.login-error:empty{display:none}\n.login-privacy{\n  font-size:12px;\n  color:var(--muted);\n  line-height:1.7;\n  border-top:1px solid var(--line);\n  padding-top:18px;\n  margin:24px 0 0;\n}\n.login-main footer{grid-column:1/-1;width:100%;margin-top:0;font-size:11px}\n\n/* ======================================================== */\n/* LIVE OWNER SUMMARY & DATA TABLES                         */\n/* ======================================================== */\n.live-main{max-width:1040px}\n.live-panel{max-width:480px;margin:24px 0}\n.live-panel label{display:block;margin:14px 0 6px;font-size:13px;font-weight:600}\n.live-panel input{\n  display:block;\n  width:100%;\n  padding:11px 14px;\n  border:1px solid #b5c7bc;\n  border-radius:var(--radius-sm);\n  background:var(--white);\n  font:inherit;\n}\n.live-panel input:focus{\n  border-color:var(--teal);\n  box-shadow:0 0 0 3px rgba(25,82,68,0.14);\n}\n.live-panel .button{margin-top:18px}\n.live-panel #connect-status{font-size:13px;color:var(--rust);min-height:20px}\n.live-stats{grid-template-columns:repeat(2,minmax(0,1fr))}\n.live-stats .business-card{min-height:170px}\n.live-table-title{margin:28px 0 12px;font-size:15px;font-weight:600;color:var(--ink)}\n.live-table-wrap{\n  overflow-x:auto;\n  background:var(--white);\n  border:1px solid var(--line);\n  border-radius:var(--radius-md);\n  box-shadow:var(--shadow-card);\n}\n.live-table{width:100%;border-collapse:collapse;text-align:left}\n.live-table th,.live-table td{\n  padding:13px 18px;\n  border-bottom:1px solid var(--line-light);\n  font-variant-numeric:tabular-nums;\n}\n.live-table th{\n  font-size:11.5px;\n  color:var(--muted);\n  text-transform:uppercase;\n  letter-spacing:0.6px;\n  background:#fafbf9;\n  font-weight:600;\n}\n.live-table tbody tr{\n  transition:background-color 0.12s ease;\n}\n.live-table tbody tr:hover{\n  background:#f2f7f4;\n}\n.live-table tr:last-child td{border-bottom:0}\n#disconnect-button{margin-top:22px}\n\n/* ======================================================== */\n/* RESPONSIVE MEDIA QUERIES                                 */\n/* ======================================================== */\n@media(min-width:1280px){main{padding-top:52px}}\n@media(max-width:1000px){\n  .business-grid{grid-template-columns:1fr 1fr}\n  .business-card:last-child{grid-column:1/-1}\n  .business-card:last-child .metric-context{min-height:0}\n  .card-top{gap:8px}\n  .metric-value{font-size:28px}\n  .business-card .card-top{flex-wrap:wrap}\n}\n@media(max-width:780px){\n  .login-main{grid-template-columns:minmax(0,1fr);gap:28px;padding-top:32px;max-width:540px}\n  .login-intro h1{font-size:38px;margin:12px 0}\n  .login-intro .subtitle{font-size:14px}\n  .login-context{margin-top:20px;padding-top:18px;max-width:none}\n  .login-session{max-width:none}\n  .login-card{padding:26px}\n  .login-main footer{margin-top:0}\n}\n@media(max-width:620px){\n  .topbar{height:72px;padding:0 18px}\n  .brand{font-size:15px;gap:9px}\n  .brand small{font-size:8px;letter-spacing:2.5px}\n  .brand-mark{width:32px;height:36px;font-size:22px}\n  .identity{gap:10px;font-size:11.5px}\n  .role{padding-left:10px}\n  .demo-label{padding:4px 9px;font-size:11px}\n  main{padding:28px 16px 0}\n  .page-heading{display:block;margin-bottom:22px}\n  h1{font-size:32px}\n  .subtitle{font-size:12.5px}\n  .period{display:inline-block;margin-top:16px;padding:9px 12px;font-size:12px}\n  .period small{display:inline;padding-left:8px;font-size:9.5px}\n  .demo-note{align-items:flex-start;font-size:11.5px;margin-bottom:26px}\n  .note-icon{margin-top:2px}\n  .attention-grid,.business-grid,.live-stats{grid-template-columns:1fr}\n  .business-card:last-child{grid-column:auto}\n  .attention-card{padding:18px}\n  .attention-card p{font-size:17px}\n  .section-caption{font-size:10.5px;max-width:110px;text-align:right}\n  h2{font-size:17px}\n  .businesses{margin-top:28px}\n  .business-card{padding:20px}\n  .business-card .card-top{margin-bottom:18px;flex-wrap:nowrap}\n  .metric-value{font-size:29px}\n  .metric-context{min-height:0;margin-bottom:18px}\n  .personal{grid-template-columns:1fr;padding:20px;margin-top:24px}\n  .personal-copy>p span{display:block}\n  .balance-control{text-align:left;margin-top:14px}\n  .privacy-note{margin-top:9px}\n  .personal h2{font-size:24px}\n  .balance{font-size:12px}\n  footer{display:block;font-size:10px;margin-top:30px}\n  footer span{display:block}\n  footer span+span{margin-top:6px}\n  .dialog-body{padding:12px 18px 18px}\n  .dialog-header{padding:16px 18px 4px}\n  .dialog-body h2{font-size:24px}\n  .detail-grid{grid-template-columns:1fr}\n  .detail-stat strong{font-size:21px}\n  .dialog-footer{padding:15px 18px}\n  .dialog-footer p{max-width:140px}\n  dl div{flex-direction:column;gap:3px}\n  dd{text-align:left}\n  .live-stats .business-card{min-height:0}\n  .live-table th,.live-table td{padding:10px 10px;font-size:11.5px}\n  .live-table-scroll{max-height:260px}\n}\n@media(max-width:420px){\n  .topbar:has(#logout-form){height:auto;min-height:84px;flex-wrap:wrap;gap:12px;padding:12px 16px}\n  .topbar:has(#logout-form) .identity{margin-left:auto;gap:10px}\n  .login-card{padding:22px 18px;border-radius:var(--radius-md)}\n  .login-card h2{font-size:26px}\n  .login-intro h1{font-size:34px}\n  .login-main{gap:24px}\n  .login-main footer{font-size:10px}\n  #logout-button{min-height:38px}\n}\n@media(prefers-reduced-motion:reduce){\n  *,::before,::after{\n    animation-duration:0.01ms!important;\n    animation-iteration-count:1!important;\n    transition-duration:0.01ms!important;\n    scroll-behavior:auto!important;\n  }\n}\n",
  "../public/money.css": ".source-tabs{\n  display:inline-flex;\n  flex-wrap:wrap;\n  gap:6px;\n  margin:0 0 32px;\n  background:#edf3ee;\n  border:1px solid var(--line);\n  padding:5px;\n  border-radius:14px;\n}\n.source-tabs a{\n  text-decoration:none;\n  display:inline-flex;\n  align-items:center;\n  padding:8px 16px;\n  border-radius:10px;\n  font-size:13px;\n  font-weight:600;\n  color:var(--muted);\n  border:1px solid transparent;\n  background:transparent;\n  box-shadow:none;\n  transition:all 0.16s cubic-bezier(0.2,0.8,0.2,1);\n}\n.source-tabs a:hover:not([aria-current=\"page\"]){\n  color:var(--ink);\n  background:rgba(255,255,255,0.65);\n}\n.source-tabs a[aria-current=\"page\"],\n.source-tabs a.primary{\n  background:var(--white);\n  color:var(--teal);\n  border-color:var(--line);\n  box-shadow:0 2px 6px rgba(20,40,38,0.06);\n}\n.money-amount{\n  font-size:21px;\n  font-weight:600;\n  font-variant-numeric:tabular-nums;\n  overflow-wrap:anywhere;\n  margin:4px 0 16px;\n  color:var(--ink);\n  letter-spacing:-0.3px;\n}\n.business-card h3{\n  font-size:17px;\n  margin:0 0 16px;\n  letter-spacing:-0.2px;\n  color:var(--ink);\n}\n.business-card .metric-label{margin:10px 0 0}\n.business-card .scope-note{font-size:12px;color:var(--amber)}\n#money-code,#pos-code,#kost-code{\n  font-size:18px;\n  font-weight:700;\n  letter-spacing:0.08em;\n  overflow-wrap:anywhere;\n  padding:12px 16px;\n  background:var(--teal-surface);\n  border:1px dashed var(--teal-border);\n  border-radius:var(--radius-sm);\n  color:var(--teal);\n  display:inline-block;\n  margin:14px 0;\n}\n#money-code:empty,#pos-code:empty,#kost-code:empty{display:none}\n",
  "./login.html": "<!doctype html>\r\n<html lang=\"id\">\r\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"color-scheme\" content=\"light\"><title>Masuk Pemilik — CHARISNA</title><link rel=\"stylesheet\" href=\"/styles.css\"><script type=\"module\" src=\"/login.mjs\"></script></head>\r\n<body class=\"login-page\">\r\n<a class=\"skip\" href=\"#main\">Lewati ke halaman masuk</a>\r\n<header class=\"topbar\"><a class=\"brand\" href=\"/login\" aria-label=\"CHARISNA SuperApp, masuk pemilik\"><span class=\"brand-mark\" aria-hidden=\"true\">C</span><span>CHARISNA <small>SUPERAPP</small></span></a><span class=\"demo-label\">Sumber nyata</span></header>\r\n<main id=\"main\" class=\"login-main\">\r\n<section class=\"login-intro\" aria-labelledby=\"intro-title\"><p class=\"eyebrow\">RUANG PEMILIK · SUMBER NYATA</p><h1 id=\"intro-title\">Satu ruang.<br>Fokus yang tepat<span class=\"title-dot\">.</span></h1><p class=\"subtitle\">Masuk untuk melihat ringkasan MySalary dalam ruang khusus pemilik.</p><div class=\"login-context\"><span class=\"note-icon\" aria-hidden=\"true\">i</span><p>MySalary perlu dihubungkan sekali pada browser ini. Gaji mengajar tetap terpisah dari omzet usaha.</p></div><p class=\"login-session\">Tetap masuk di perangkat pribadi. Sesi diperpanjang otomatis dan berakhir setelah 30 hari tidak digunakan. Keluar jika memakai perangkat bersama.</p></section>\r\n<section class=\"login-card\" aria-labelledby=\"login-title\"><p class=\"eyebrow\">AKSES KHUSUS PEMILIK</p><h2 id=\"login-title\">Selamat datang kembali</h2><p class=\"login-description\">Masuk dengan email dan sandi pemilik. Perangkat pribadi akan mengingat sesi Anda.</p>\r\n<form id=\"password-form\" action=\"/auth/login\" method=\"post\">\r\n<label for=\"owner-email\">Email pemilik</label><input id=\"owner-email\" name=\"email\" type=\"email\" autocomplete=\"username\" value=\"charisna.superapp@gmail.com\" readonly required>\r\n<label for=\"password\">Sandi</label><input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"current-password\" minlength=\"8\" maxlength=\"256\" required>\r\n<button id=\"password-login\" class=\"button primary\" type=\"submit\" disabled>Masuk</button>\r\n</form>\r\n<details><summary>Belum punya sandi atau lupa sandi?</summary><p class=\"field-hint\">Gunakan tautan pemulihan sekali, lalu atur sandi dari pengaturan keamanan. Buka tautan di peramban yang sama.</p>\r\n<form id=\"send-link-form\" action=\"/auth/send-link\" method=\"post\"><button id=\"send-link\" class=\"button primary\" type=\"submit\" disabled>Kirim tautan masuk</button><p id=\"send-cooldown\" class=\"field-hint\">Tautan hanya dikirim ke email pemilik terdaftar.</p></form></details>\r\n<p id=\"login-status\" class=\"login-status\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p><p id=\"login-error\" class=\"login-error\" role=\"alert\" aria-atomic=\"true\"></p>\r\n<noscript><p>Aktifkan JavaScript untuk masuk dengan aman. Tautan hanya dikirim ke email pemilik terdaftar.</p></noscript>\r\n<p class=\"login-privacy\">Akses diverifikasi oleh server. Data MySalary hanya dibaca setelah akun sumber dihubungkan.</p>\r\n</section>\r\n<footer><span>CHARISNA SuperApp</span><span>Data MySalary · hanya baca · khusus pemilik</span></footer>\r\n</main></body></html>\r\n",
  "./login.mjs": "const postOptions = body => ({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),cache:'no-store'});\r\n\r\nexport function createLoginController({fetch:request=globalThis.fetch,now=Date.now,onChange=()=>{},onSuccess=()=>{},initialError=''}={}) {\r\n let busy=false,availableAt=0,message='',error=initialError;\r\n const controller={\r\n  get state(){return {busy,cooldown:Math.max(0,Math.ceil((availableAt-now())/1000)),message,error};},\r\n  async signIn(password){\r\n   if(busy)return;\r\n   busy=true;message='';error='';onChange(controller.state);\r\n   try{\r\n    const response=await request('/auth/login',postOptions({password}));\r\n    if(response.ok){onSuccess();return;}\r\n    error=response.status===429?'Terlalu banyak percobaan. Tunggu 15 menit, lalu coba lagi.':response.status===401||response.status===403?'Sandi atau email tidak sesuai. Coba lagi atau gunakan pemulihan akun.':'Permintaan belum dapat diproses. Coba lagi nanti.';\r\n   }catch{error='Permintaan belum dapat diproses. Periksa koneksi internet.';}\r\n   finally{busy=false;onChange(controller.state);}\r\n  },\r\n  async sendLink(){\r\n   if(busy||controller.state.cooldown)return;\r\n   busy=true;message='';error='';onChange(controller.state);\r\n   // A failed request may still have delivered a link: always throttle retries.\r\n   availableAt=now()+60000;\r\n   try {\r\n    const response=await request('/auth/send-link',postOptions({}));\r\n    if(!response.ok)throw Error('request');\r\n    message='Jika permintaan dapat diproses, tautan akan dikirim ke email pemilik terdaftar. Periksa kotak masuk dan spam, lalu buka tautan di peramban ini.';\r\n   } catch {error='Permintaan belum dapat diproses. Tunggu sebentar, lalu coba lagi.';}\r\n   finally {busy=false;onChange(controller.state);}\r\n  }\r\n };\r\n return controller;\r\n}\r\n\r\nexport function mountLogin({document=globalThis.document,window=globalThis.window,fetch=globalThis.fetch,now=Date.now}={}) {\r\n const $=selector=>document.querySelector(selector);\r\n function render(state){\r\n  $('#password-login').disabled=state.busy;\r\n  $('#password-form').setAttribute('aria-busy',String(state.busy));\r\n  $('#send-link').disabled=state.busy||state.cooldown>0;\r\n  $('#send-link-form').setAttribute('aria-busy',String(state.busy));\r\n  $('#send-cooldown').textContent=state.cooldown?`Kirim ulang tersedia dalam ${state.cooldown} detik.`:'Tautan hanya dikirim ke email pemilik terdaftar.';\r\n  $('#send-link').textContent=state.busy?'Mohon tunggu…':'Kirim tautan masuk';\r\n  if($('#login-status').textContent!==state.message)$('#login-status').textContent=state.message;\r\n  if($('#login-error').textContent!==state.error)$('#login-error').textContent=state.error;\r\n }\r\n const failed=new URLSearchParams(window.location.search).has('error');\r\n const controller=createLoginController({fetch,now,onChange:render,onSuccess:()=>window.location.replace('/'),initialError:failed?'Tautan tidak valid, kedaluwarsa, atau dibuka di peramban lain. Minta tautan baru.':''});\r\n $('#password-form').addEventListener('submit',async event=>{\r\n  event.preventDefault();const password=$('#password').value;$('#password').value='';await controller.signIn(password);\r\n });\r\n $('#send-link-form').addEventListener('submit',async event=>{event.preventDefault();await controller.sendLink();});\r\n window.addEventListener('pagehide',()=>{$('#password').value='';});\r\n const ticker=window.setInterval(()=>render(controller.state),1000);\r\n window.addEventListener('pagehide',()=>window.clearInterval(ticker));\r\n window.addEventListener('pageshow',event=>{if(event.persisted)window.location.reload();});\r\n render(controller.state);\r\n return controller;\r\n}\r\nif(typeof document!=='undefined')mountLogin();",
  "./security.html": "<!doctype html><html lang=\"id\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>CHARISNA — Keamanan akun</title><link rel=\"stylesheet\" href=\"/styles.css\"><script type=\"module\" src=\"/device.mjs\"></script></head><body class=\"login-page\"><header class=\"topbar\"><a class=\"brand\" href=\"/\">CHARISNA <small>SUPERAPP</small></a><a class=\"button secondary\" href=\"/\">Ringkasan</a></header><main class=\"login-main\"><section class=\"login-card\"><p class=\"eyebrow\">KHUSUS PEMILIK</p><h1>Keamanan akun</h1><p class=\"login-description\">Email: charisna.superapp@gmail.com. Sandi dan data biometrik tidak disimpan di kode aplikasi.</p><h2>Atur sandi login</h2><form id=\"set-password-form\"><label for=\"new-password\">Sandi baru</label><input id=\"new-password\" type=\"password\" autocomplete=\"new-password\" minlength=\"8\" maxlength=\"128\" required><label for=\"confirm-password\">Ulangi sandi baru</label><input id=\"confirm-password\" type=\"password\" autocomplete=\"new-password\" minlength=\"8\" maxlength=\"128\" required><button id=\"save-password\" class=\"button primary\" type=\"submit\">Simpan sandi</button></form><h2>Buka kunci perangkat</h2><p class=\"field-hint\">Aktifkan sekali pada setiap perangkat pribadi. Setelah 15 menit, akses data dikunci di server sampai diverifikasi kembali. PIN Windows Hello, sidik jari, atau pengenalan wajah mengikuti fitur perangkat. SuperApp tidak membaca atau menyimpan PIN, sidik jari, maupun wajah.</p><button id=\"register-device\" class=\"button primary\" type=\"button\">Aktifkan PIN / biometrik</button><p class=\"field-hint\">Sesi akun bertahan sampai 30 hari tanpa aktivitas. Jika sesi habis, cookie dihapus, atau Anda keluar, masuk kembali dengan email dan sandi. Jangan aktifkan pada perangkat bersama.</p><button id=\"revoke-device\" class=\"button secondary\" type=\"button\">Hapus semua kunci perangkat</button><p id=\"device-status\" role=\"status\" aria-live=\"polite\"></p></section></main></body></html>",
  "./unlock.html": "<!doctype html><html lang=\"id\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>CHARISNA — Perangkat terkunci</title><link rel=\"stylesheet\" href=\"/styles.css\"><script type=\"module\" src=\"/device.mjs\"></script></head><body class=\"login-page\"><header class=\"topbar\"><a class=\"brand\" href=\"/\">CHARISNA <small>SUPERAPP</small></a><a class=\"button secondary\" href=\"/\">Ringkasan</a></header><main class=\"login-main\"><section class=\"login-card\"><p class=\"eyebrow\">PERANGKAT TERKUNCI</p><h1>Selamat datang kembali</h1><p class=\"login-description\">Sesi pemilik masih aktif. Verifikasi dengan PIN atau biometrik perangkat untuk membuka ringkasan.</p><button id=\"unlock-button\" class=\"button primary\" type=\"button\">Buka dengan PIN / biometrik</button><p class=\"field-hint\">Pilihan PIN, sidik jari, atau wajah disediakan oleh sistem perangkat. Jika tidak tersedia, gunakan email dan sandi.</p><a class=\"button secondary\" href=\"/login\">Masuk dengan sandi</a><form id=\"logout-form\"><button class=\"button secondary\" type=\"submit\">Keluar dari akun</button></form><p id=\"device-status\" role=\"status\" aria-live=\"polite\"></p></section></main></body></html>",
  "./device.mjs": "const decode = text => Uint8Array.from(atob(text.replace(/-/g,'+').replace(/_/g,'/')), c=>c.charCodeAt(0));\r\nconst encode = data => btoa(String.fromCharCode(...new Uint8Array(data))).replace(/\\+/g,'-').replace(/\\//g,'_').replace(/=+$/,'');\r\nexport function webAuthnOptions(options){\r\n const result={...options,challenge:decode(options.challenge)};\r\n if(options.user)result.user={...options.user,id:decode(options.user.id)};\r\n for(const key of ['allowCredentials','excludeCredentials'])if(options[key])result[key]=options[key].map(c=>({...c,id:decode(c.id)}));\r\n return result;\r\n}\r\nexport function credentialJSON(credential){\r\n const response={};\r\n for(const key of ['clientDataJSON','attestationObject','authenticatorData','signature','userHandle'])if(key in credential.response)response[key]=credential.response[key]==null?null:encode(credential.response[key]);\r\n if(credential.response.getTransports)response.transports=credential.response.getTransports();\r\n return {id:credential.id,rawId:encode(credential.rawId),type:credential.type,response,authenticatorAttachment:credential.authenticatorAttachment,clientExtensionResults:credential.getClientExtensionResults()};\r\n}\r\nexport function mountDevice({document=globalThis.document,window=globalThis.window,fetch=globalThis.fetch}={}){\r\n const $=s=>document.querySelector(s);let busy=false;\r\n async function post(path,body={}){\r\n  const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),cache:'no-store'});\r\n  if(r.status===401){window.location.replace('/login');throw Error('Silakan masuk kembali.');}\r\n  if(r.status===423){window.location.replace('/unlock');throw Error('Buka kunci perangkat terlebih dahulu.');}\r\n  if(!r.ok){\r\n   let msg;try{const d=await r.json();msg=d.error||d.message;}catch{}\r\n   throw Error(msg||(r.status===429?'Terlalu banyak percobaan. Coba lagi nanti.':'Permintaan belum berhasil. Coba lagi atau masuk dengan sandi.'));\r\n  }\r\n  return r.json();\r\n }\r\n async function action(button,fn){\r\n  if(busy)return;busy=true;button.disabled=true;$('#device-status').textContent='Memproses…';\r\n  try{await fn();}catch(e){$('#device-status').textContent=['NotAllowedError','AbortError'].includes(e.name)?'Verifikasi dibatalkan atau perangkat belum siap. Coba lagi.':e.name==='InvalidStateError'?'Kunci ini sudah terdaftar. Gunakan buka kunci.':e.message;}\r\n  finally{busy=false;button.disabled=false;}\r\n }\r\n const register=$('#register-device');\r\n if(register)register.addEventListener('click',()=>action(register,async()=>{\r\n  if(!window.PublicKeyCredential||!window.navigator?.credentials)throw Error('Peramban ini belum mendukung kunci perangkat. Gunakan Chrome, Edge, atau Safari terbaru melalui HTTPS.');\r\n  if(window.PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable&&!await window.PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable())throw Error('Aktifkan Windows Hello, Touch ID, Face ID, atau kunci layar perangkat terlebih dahulu.');\r\n  const options=await post('/auth/passkeys/register-options');\r\n  const credential=await window.navigator.credentials.create({publicKey:webAuthnOptions(options)});\r\n  await post('/auth/passkeys/register',credentialJSON(credential));\r\n  $('#device-status').textContent='Kunci perangkat aktif. PIN atau biometrik dipilih oleh perangkat, bukan SuperApp.';\r\n }));\r\n const unlock=$('#unlock-button');\r\n if(unlock)unlock.addEventListener('click',()=>action(unlock,async()=>{\r\n  if(!window.PublicKeyCredential||!window.navigator?.credentials)throw Error('Kunci perangkat tidak tersedia. Masuk kembali dengan email dan sandi.');\r\n  const options=await post('/auth/passkeys/authenticate-options');\r\n  const credential=await window.navigator.credentials.get({publicKey:webAuthnOptions(options)});\r\n  await post('/auth/passkeys/authenticate',credentialJSON(credential));window.location.replace('/');\r\n }));\r\n const form=$('#set-password-form');\r\n if(form)form.addEventListener('submit',event=>{event.preventDefault();\r\n  const password=$('#new-password').value,confirmation=$('#confirm-password').value;$('#new-password').value='';$('#confirm-password').value='';\r\n  if(password!==confirmation){$('#device-status').textContent='Konfirmasi sandi tidak sama.';return;}\r\n  return action($('#save-password'),async()=>{await post('/auth/password',{password});$('#device-status').textContent='Sandi tersimpan. Login berikutnya gunakan email dan sandi ini.';});\r\n });\r\n const revoke=$('#revoke-device');\r\n if(revoke)revoke.addEventListener('click',()=>{if(!window.confirm('Hapus semua kunci perangkat? Login dengan email dan sandi tetap tersedia.'))return;return action(revoke,async()=>{await post('/auth/passkeys/revoke');$('#device-status').textContent='Semua kunci perangkat dihapus. Email dan sandi tetap dapat digunakan.';});});\r\n const logout=$('#logout-form');\r\n if(logout)logout.addEventListener('submit',async e=>{e.preventDefault();try{await post('/auth/logout');}finally{window.location.replace('/login');}});\r\n}\r\nif(typeof document!=='undefined')mountDevice();\r\n"
});

export function loadAsset(file) {
  if (!Object.hasOwn(assets, file)) throw new Error('Unknown embedded asset');
  return assets[file];
}
